"""Installation and selection: distinct counts, defense and witness absence."""
import json,sys
from pathlib import Path
CPP='https://www.planalto.gov.br/ccivil_03/decreto-lei/del3689compilado.htm'
rows={}
def add(n,s,p,a,c,v,q,t,d):
 rows['art-'+str(n)]=dict(simples=s,pontos=p,atencao=[a],exemplo=c+' Variação: '+v,prova=q,termos=[dict(termo=t,significado=d)],remissoes=[CPP])
add(451,'Jurados excluídos por impedimento, suspeição ou incompatibilidade contam para o número legal de realização da sessão.', ['Contagem para instalar não é aptidão para votar.', 'Integrar art. 463.'], 'Não sortear impedido para Conselho só porque contou no número de presentes.', 'Dezesseis presentes incluem um impedido: a contagem legal não o habilita a julgar.', 'Seleção dos sete deve conservar aptidão individual.', ['Excluído pode contar para instalação? Sim.', 'Isso permite votar apesar do impedimento? Não.'], 'Quórum e aptidão','Contagem da sessão distinta de capacidade de integrar Conselho.')
add(452,'Mesmo Conselho pode julgar mais de um processo no mesmo dia se partes aceitarem e houver novo compromisso.', ['Aceitação das partes necessária.', 'Novo compromisso em cada caso.', 'Impedimentos próprios continuam aplicáveis.'], 'Concordância não torna jurado impedido apto para nova causa.', 'Conselho apto é aceito pelas partes e presta novo compromisso para segundo processo.', 'Falta de aceitação impede usar regra como simples conveniência administrativa.', ['Novo compromisso é necessário? Sim.', 'Dispensa aceitação das partes? Não.'], 'Reutilização do Conselho','Atuação em outra causa sob condições legais.')
add(453,'Períodos e forma das reuniões seguem lei local de organização judiciária.', ['Distinguir organização local de garantias processuais nacionais.', 'Consultar norma competente para calendário.'], 'Não inventar calendário nacional único nem permitir lei local afastar defesa.', 'Tribunal agenda reuniões segundo sua organização legal.', 'Calendário local não dispensa intimações e composição previstas no CPP.', ['Há calendário universal definido aqui? Não.', 'A lei local organiza as reuniões? Sim.'], 'Organização local','Regras legais de períodos e funcionamento.')
add(454,'Até abertura dos trabalhos, presidente decide isenções, dispensas e pedido de adiamento, registrando em ata.', ['Examinar fundamentos.', 'Consignar deliberações.'], 'Pedido não concede dispensa ou adiamento por si só.', 'Jurado apresenta motivo e presidente decide com registro.', 'Parte não presume sessão cancelada apenas por ter requerido adiamento.', ['Deliberações devem constar de ata? Sim.', 'Requerimento já cancela sessão? Não.'], 'Decisões preliminares','Providências anteriores à abertura formal.')
add(455,'Ausência do MP adia para primeiro dia desimpedido da mesma reunião, com ciência das partes e testemunhas.', ['Falta injustificada comunicada imediatamente ao Procurador-Geral de Justiça.', 'Comunicar também nova data.'], 'Não prosseguir substituindo acusação pública pelo juiz presidente.', 'Promotor ausente leva a adiamento e comunicações previstas.', 'Se falta é justificada, isso não torna juiz parte acusadora.', ['Juiz pode substituir MP na acusação? Não.', 'Ausência injustificada deve ser comunicada? Sim.'], 'Ausência do MP','Falta do órgão acusador com consequência processual própria.')
add(456,'Falta injustificada de advogado sem substituto leva a comunicação à OAB e um adiamento, preservando defesa na nova sessão.', ['Intimar Defensoria para novo julgamento.', 'Primeiro dia desimpedido respeitando mínimo de dez dias.', 'Hipótese pressupõe ausência sem escusa legítima.'], 'Julgar na próxima chamada não significa julgar sem defensor preparado.', 'Após falta injustificada, Defensoria recebe intimação com antecedência mínima.', 'Escusa legítima deve ser examinada antes de aplicar limite de adiamento.', ['Nova sessão dispensa defensor? Não.', 'Mínimo para novo julgamento é dez dias? Sim.'], 'Defesa substitutiva','Garantia de assistência diante da falta injustificada do advogado.')
add(457,'Ausência de acusado solto, assistente ou advogado do querelante regularmente intimados não adia por si julgamento.', ['Justificativas/pedidos prévio exame, salvo força maior comprovada.', 'Preso não apresentado: adiamento, salvo dispensa subscrita por ele e defensor.', 'Defesa técnica do acusado permanece.'], 'Não generalizar ausência do solto para preso nem aceitar dispensa do preso apenas pela assinatura do advogado.', 'Solto regularmente intimado não comparece: examina-se prosseguimento com defesa.', 'Preso não conduzido só pode ter hipótese de dispensa pertinente com ambas as assinaturas.', ['Dispensa do preso exige ele e defensor? Sim.', 'Ausência do solto elimina defesa técnica? Não.'], 'Presença no plenário','Regras distintas conforme liberdade e manifestação válida.')
add(458,'Testemunha ausente sem justa causa sujeita-se à multa do art. 436, §2º, sem prejuízo de apuração de desobediência.', ['Multa de um a dez salários mínimos no regime remetido.', 'Verificar regular convocação e causa da ausência.', 'Desobediência requer apuração dos requisitos, não condenação sumária.'], 'Ausência não prova automaticamente crime nem dispensa análise de justa causa.', 'Testemunha regularmente intimada falta sem motivo: sanção é examinada.', 'Emergência comprovada muda análise da justa causa.', ['Justa causa precisa ser examinada? Sim.', 'Falta equivale a condenação automática por crime? Não.'], 'Falta de testemunha','Inadimplemento sujeito a consequências legalmente apuradas.')
add(459,'Testemunha a serviço do júri recebe a proteção remuneratória do art. 441.', ['Integrar comparecimento e comprovação.', 'Não é benefício reservado só aos jurados.'], 'Não descontar salário pela participação regular como testemunha nas condições legais.', 'Empregada comparece como testemunha e comprova participação.', 'Ausência sem participação não gera documento fictício para justificar dia.', ['Proteção pode alcançar testemunha? Sim.', 'Autoriza comprovar presença inexistente? Não.'], 'Remuneração da testemunha','Proteção salarial pela participação pertinente.')
add(460,'Antes de formar Conselho, testemunhas ficam em local que impeça ouvir depoimentos umas das outras.', ['Preservar independência dos relatos.', 'Organizar espera sem contaminação probatória.'], 'Não permitir acompanhar depoimento anterior só por conveniência logística.', 'Testemunhas aguardam separadas da oitiva em andamento.', 'Sala com transmissão dos depoimentos contraria finalidade da separação.', ['Separação busca independência dos relatos? Sim.', 'Pode ouvir depoimento anterior sem restrição? Não.'], 'Separação de testemunhas','Prevenção de influência entre depoimentos.')
add(461,'Falta de testemunha só tem hipótese específica de adiamento se requerida intimação por mandado no art. 422, indispensabilidade e localização.', ['Se intimada não comparece: suspender e conduzir ou adiar com condução.', 'Se não encontrada no endereço indicado e certificado, julgamento ocorre.', 'Não confundir com condução de réu para interrogatório.'], 'Indicar nome sem declarar não prescindir e sem localização não preenche automaticamente exceção.', 'Parte requereu mandado, indicou local e indispensabilidade; testemunha intimada falta: aplicar providência legal.', 'Não encontrada no endereço certificado leva à regra de realização do §2º.', ['Só nome no rol basta para exceção? Não.', 'Não encontrada certificadamente impede sempre julgamento? Não.'], 'Testemunha indispensável','Exceção condicionada ao requerimento e diligência previstos.')
add(462,'Após providências preliminares, presidente verifica cédulas dos vinte e cinco sorteados e manda realizar chamada.', ['Verificação antecede instalação e Conselho.', 'Chamada identifica comparecimento.'], 'Existirem 25 cédulas não demonstra que compareceram 25 jurados.', 'Urna é conferida e nomes são chamados.', 'Quórum depende dos presentes segundo regras, não apenas do conteúdo da urna.', ['Cédulas provam comparecimento por si? Não.', 'Chamada segue verificação? Sim.'], 'Conferência da urna','Controle da seleção e da presença.')
add(463,'Com pelo menos quinze jurados presentes, presidente instala trabalhos e anuncia processo, com pregão certificado.', ['Excluídos por impedimento/suspeição computam no número legal.', 'Conselho de sete é formado depois.', 'Integrar contagem do art. 451.'], 'Não confundir quórum de instalação de quinze com os sete que julgam ou 25 sorteados.', 'Quinze presentes satisfazem número legal nas condições previstas.', 'Quatorze presentes exigem providências do art. 464, não instalação por haver sete aptos.', ['Quórum mínimo de instalação é quinze? Sim.', 'Sete aptos bastam sempre para instalar? Não.'], 'Instalação dos trabalhos','Abertura com número legal de presentes.')
add(464,'Sem número legal, sorteiam-se suplentes necessários e marca-se nova data.', ['Não completar informalmente com espectadores.', 'Providência de nova convocação.'], 'Falta de quinze não é resolvida por reduzir Conselho ou dispensar quórum.', 'Quórum insuficiente leva ao sorteio de suplentes e redesignação.', 'Pessoas da plateia não viram juradas sem regime legal.', ['Há designação de nova data? Sim.', 'Plateia supre quórum informalmente? Não.'], 'Suplementação do quórum','Seleção legal de suplentes para nova sessão.')
add(465,'Nomes dos suplentes ficam na ata e convocação observa arts. 434 e 435.', ['Registro e comunicação formal.', 'Não basta seleção sem ciência hábil.'], 'Sorteio de suplente não equivale a comparecimento ou convocação efetiva.', 'Suplentes sorteados são documentados e regularmente chamados.', 'Nome apenas em anotação interna não comprova ciência suficiente.', ['Nomes devem constar da ata? Sim.', 'Convocação segue regime indicado? Sim.'], 'Convocação de suplentes','Registro e ciência dos cidadãos adicionais.')
add(466,'Antes de sortear Conselho, presidente explica impedimentos e adverte sobre incomunicabilidade e opinião sobre o processo.', ['Sorteados não podem comunicar-se entre si ou terceiros sobre contexto do processo, nem manifestar opinião.', 'Exclusão e multa previstas para violação.', 'Oficial certifica incomunicabilidade.'], 'Não transformar proibição em isolamento desumano de necessidades ordinárias; preservar a finalidade de independência sobre a causa.', 'Jurado não comenta mérito com outro julgador durante julgamento.', 'Atendimento de necessidade prática sob controle não autoriza discussão da prova.', ['Incomunicabilidade é certificada? Sim.', 'Podem trocar opiniões sobre mérito? Não.'], 'Incomunicabilidade','Garantia de decisão independente, sem discussão da causa.')
add(467,'Conferidas cédulas dos presentes, presidente sorteia sete para Conselho.', ['Selecionar dentre presentes aptos.', 'Aplicar impedimentos e recusas.'], 'Não sortear ausente apenas porque seu cartão está entre os convocados.', 'Juiz verifica presentes e realiza seleção de sete.', 'Impedido contado para instalação continua excluído do Conselho.', ['Seleção é dentre presentes? Sim.', 'Contar para instalação cura impedimento? Não.'], 'Sorteio do Conselho','Formação dos sete julgadores da causa.')
add(468,'Defesa e depois MP podem recusar até três sorteados cada, sem motivar.', ['Leitura da cédula pelo presidente.', 'Recusado imotivadamente é excluído daquela sessão.', 'Sorteio prossegue com remanescentes.', 'Distinguir recusa imotivada de arguição fundada de impedimento.'], 'Não inverter ordem nem limitar toda impugnação fundamentada ao teto das recusas sem motivo.', 'Defesa recusa um jurado sem justificar e MP faz sua avaliação após ela.', 'Impedimento legal alegado exige análise própria, não mero consumo automático do teto imotivado.', ['Defesa manifesta-se antes do MP? Sim.', 'Limite imotivado é três por parte? Sim.'], 'Recusa imotivada','Exclusão limitada sem necessidade de fundamento declarado.')
add(469,'Com vários acusados, um defensor pode exercer recusas; separação só ocorre se elas impedirem obter sete jurados.', ['Separados, julga-se primeiro a quem atribuída autoria.', 'Coautoria: preferência do art. 429.', 'Não separar apenas por existirem duas defesas.'], 'Número de acusados não impõe cisão automática dos julgamentos.', 'Recusas deixam menos de sete aptos: separação é examinada conforme artigo.', 'Com sete aptos após recusas, não se invoca essa causa de separação só pela pluralidade de réus.', ['Dois acusados exigem separação automática? Não.', 'Falta de sete por recusas é a condição prevista? Sim.'], 'Separação por recusas','Cisão para viabilizar composição regular.')
add(470,'Rejeitada arguição de impedimento/suspeição/incompatibilidade, julgamento não suspende, mas fundamento e decisão constam da ata.', ['Abrange presidente, MP, jurado ou funcionário.', 'Preservar registro para controle pertinente.'], 'Prosseguir não significa ignorar pedido nem dispensar sua documentação.', 'Juiz rejeita arguição e registra motivos e decisão.', 'Anotação vazia de pedido rejeitado sem fundamento não satisfaz o registro exigido.', ['Rejeição suspende automaticamente? Não.', 'Fundamento e decisão precisam de registro? Sim.'], 'Registro da arguição','Documentação da questão rejeitada sem paralisação automática.')
rows['art-466']['pontos'].append('STJ, 2025: uso prolongado de celular nos debates compromete independência e pode gerar nulidade; não tratar telefone como comunicação livre.')
rows['art-466']['remissoes'].append('https://scon.stj.jus.br/SCON/GetInteiroTeorDoAcordao?num_registro=202402817414')
assert len(rows)==20
Path(sys.argv[1]).write_text(json.dumps({'course_slug':'codigo-processo-penal','units':rows},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(len(rows),'jury installation units reviewed')
